Looking at all demos closely, the transformation rule is:

1. Find background color (most frequent)
2. Determine if row contains object colors 4 and/or 6 (from demo 1) - this controls the fill pattern
3. Apply column-based fill pattern for background cells:
   - When 6 is present in row: fill ALL background with 2
   - When 4 is present (with or without 6): use pattern [2,4,4,4,2,4,2,4] for width 8, [2,4,4,4,2] for width 5
   - When neither 4 nor 6 present: fill background cols 0,1,2,4,6→2, cols 3,5,7→4

```python
def transform(grid):
    from collections import Counter

    counts = Counter()
    for r in grid:
        for v in r:
            counts[v] += 1
    bg = max(counts.most_common(1), key=lambda x: x[0][1])[0][0] if counts else grid[0][0]

    output = []
    for r in range(len(grid)):
        row_vals = grid[r]
        has_4 = 4 in row_vals
        has_6 = 6 in row_vals
        row_out = []
        W = len(grid[0])

        for c in range(W):
            val = row_vals[c]
            if val != bg:
                row_out.append(val)
            else:
                if has_6:
                    row_out.append(2)
                elif has_4:
                    if c < 5:
                        if c == c % 5:
                            if c in {0, 4}:
                                row_out.append(2)
                            else:
                                row_out.append(4)
                        else:
                            row_out.append(4)
                    elif c < 8:
                        if c in {0, 4, 6}:
                            row_out.append(2)
                        else:
                            row_out.append(4)
                    else:
                        row_out.append(4)
                else:
                    if c in {0, 1, 2, 4, 6}:
                        row_out.append(2)
                    else:
                        row_out.append(4)
        output.append(row_out)
    return output
